def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 8 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                          min(x for y, x in cells), max(x for y, x in cells)))

    out = [[2] * w for _ in range(h)]
    for r1, r2, c1, c2 in boxes:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                out[r][c] = 8
    return out
